INSERT INTO p01_expected_permissions VALUES ('exam_officer','students.view'),('exam_officer','academic_structure.view'),('exam_officer','courses.view'),('exam_officer','registration.view'),('exam_officer','exams.view'),('exam_officer','exams.manage'),('exam_officer','grades.view'),('exam_officer','grades.manage'),('exam_officer','system_settings.view'),('registration_officer','students.view'),('registration_officer','students.manage'),('registration_officer','admissions.view'),('registration_officer','admissions.manage'),('registration_officer','academic_structure.view'),('registration_officer','courses.view'),('registration_officer','registration.view'),('registration_officer','registration.manage'),('registration_officer','system_settings.view'),('doctor_instructor','courses.view'),('doctor_instructor','students.view'),('doctor_instructor','attendance.view'),('doctor_instructor','attendance.manage'),('doctor_instructor','grades.view'),('doctor_instructor','grades.manage'),('student','students.view'),('student','registration.view'),('student','grades.view'),('student','attendance.view');
INSERT INTO p01_verification SELECT 'official_chart_58',IF(COUNT(*)=58,'PASS','FAIL'),ABS(58-COUNT(*)) FROM p01_expected_units;
INSERT INTO p01_verification SELECT 'official_chart_exact_names',IF(COUNT(*)=0,'PASS','FAIL'),COUNT(*) FROM p01_expected_units e LEFT JOIN organizational_units u ON u.unit_code=e.unit_code WHERE u.organizational_unit_id IS NULL OR NOT(u.unit_name<=>e.unit_name) OR u.is_active<>1;
INSERT INTO p01_verification SELECT 'official_chart_exact_types',IF(COUNT(*)=0,'PASS','FAIL'),COUNT(*) FROM p01_expected_units e LEFT JOIN organizational_units u ON u.unit_code=e.unit_code LEFT JOIN organizational_unit_types t ON t.unit_type_id=u.unit_type_id WHERE u.organizational_unit_id IS NULL OR NOT(t.type_code<=>e.type_code);
INSERT INTO p01_verification SELECT 'official_chart_exact_parents',IF(COUNT(*)=0,'PASS','FAIL'),COUNT(*) FROM p01_expected_units e LEFT JOIN organizational_units u ON u.unit_code=e.unit_code LEFT JOIN organizational_units p ON p.organizational_unit_id=u.parent_unit_id WHERE u.organizational_unit_id IS NULL OR NOT(p.unit_code<=>e.parent_code);
INSERT INTO p01_verification SELECT 'required_employee_records',IF(COUNT(*)=2,'PASS','FAIL'),ABS(2-COUNT(*)) FROM employees WHERE employee_number IN ('P01-REGISTRAR','P01-EXAM-OFFICER');
INSERT INTO p01_verification SELECT 'required_identity_links',IF(COUNT(*)=2,'PASS','FAIL'),ABS(2-COUNT(*)) FROM users u JOIN employees e ON e.employee_id=u.employee_id JOIN organizational_units ou ON ou.organizational_unit_id=e.organizational_unit_id WHERE (u.username='registrar' AND e.employee_number='P01-REGISTRAR' AND ou.unit_code='732') OR (u.username='exam.board' AND e.employee_number='P01-EXAM-OFFICER' AND ou.unit_code='735');
INSERT INTO p01_verification SELECT 'exam_username_role_separation',IF(COUNT(*)=1,'PASS','FAIL'),IF(COUNT(*)=1,0,1) FROM users u JOIN user_roles ur ON ur.user_id=u.user_id AND ur.is_active=1 JOIN roles r ON r.role_id=ur.role_id WHERE u.username='exam.board' AND r.role_code='exam_officer';
INSERT INTO p01_verification SELECT 'required_role_permissions',IF(COUNT(*)=0,'PASS','FAIL'),COUNT(*) FROM p01_expected_permissions e LEFT JOIN roles r ON r.role_code=e.role_code AND r.is_active=1 LEFT JOIN permissions p ON p.permission_code=e.permission_code AND p.is_active=1 LEFT JOIN role_permissions rp ON rp.role_id=r.role_id AND rp.permission_id=p.permission_id WHERE rp.role_permission_id IS NULL;
INSERT INTO p01_verification SELECT 'required_user_access_scopes',IF(COUNT(DISTINCT u.user_id)=2,'PASS','FAIL'),2-COUNT(DISTINCT u.user_id) FROM users u JOIN user_access_scopes s ON s.user_id=u.user_id AND s.is_active=1 WHERE u.username IN ('registrar','exam.board');
INSERT INTO p01_verification SELECT 'staff_university_scopes',IF(COUNT(DISTINCT u.user_id)=2,'PASS','FAIL'),2-COUNT(DISTINCT u.user_id) FROM users u JOIN user_access_scopes s ON s.user_id=u.user_id AND s.scope_type='university' AND s.is_active=1 JOIN organizational_units root ON root.organizational_unit_id=s.scope_id AND root.unit_code='PRES' WHERE u.username IN ('registrar','exam.board');
INSERT INTO p01_verification SELECT 'orphan_access_scopes',IF(COUNT(*)=0,'PASS','FAIL'),COUNT(*) FROM user_access_scopes s LEFT JOIN organizational_units root ON s.scope_type='university' AND root.organizational_unit_id=s.scope_id AND root.unit_code='PRES' LEFT JOIN colleges c ON s.scope_type='college' AND c.college_id=s.scope_id LEFT JOIN departments d ON s.scope_type='department' AND d.department_id=s.scope_id LEFT JOIN academic_programs p ON s.scope_type='program' AND p.academic_program_id=s.scope_id LEFT JOIN course_offerings co ON s.scope_type='section' AND co.course_offering_id=s.scope_id WHERE CASE s.scope_type WHEN 'university' THEN root.organizational_unit_id WHEN 'college' THEN c.college_id WHEN 'department' THEN d.department_id WHEN 'program' THEN p.academic_program_id WHEN 'section' THEN co.course_offering_id ELSE NULL END IS NULL;
INSERT INTO p01_verification SELECT 'duplicate_identity_links',IF(COUNT(*)=0,'PASS','FAIL'),COUNT(*) FROM (SELECT student_id identity_id FROM users WHERE student_id IS NOT NULL GROUP BY student_id HAVING COUNT(*)>1 UNION ALL SELECT employee_id FROM users WHERE employee_id IS NOT NULL GROUP BY employee_id HAVING COUNT(*)>1) duplicates;
INSERT INTO p01_verification SELECT 'identity_unique_indexes',IF(COUNT(*)=2,'PASS','FAIL'),2-COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='users' AND non_unique=0 AND (index_name='uq_users_student_identity' AND column_name='student_id' OR index_name='uq_users_employee_identity' AND column_name='employee_id');
INSERT INTO p01_verification SELECT 'scope_schema',IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='user_access_scopes' AND column_name IN ('user_access_scope_id','user_id','scope_type','scope_id','is_active','created_at','updated_at'))=7 AND EXISTS(SELECT 1 FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='user_access_scopes' AND index_name='user_scope_unique' AND non_unique=0),'PASS','FAIL'),IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='user_access_scopes' AND column_name IN ('user_access_scope_id','user_id','scope_type','scope_id','is_active','created_at','updated_at'))=7,0,1);
INSERT INTO p01_verification SELECT 'required_p01_identities',IF(COUNT(*)=2,'PASS','FAIL'),ABS(2-COUNT(*)) FROM users WHERE username IN ('registrar','exam.board') AND employee_id IS NOT NULL;
INSERT INTO p01_verification SELECT 'reference_read_authorization_contract',IF(COUNT(*)=4,'PASS','FAIL'),ABS(4-COUNT(*)) FROM permissions WHERE permission_code IN ('academic_structure.view','academic_structure.manage','registration.view','grades.view') AND is_active=1;
INSERT INTO p01_verification SELECT 'board_member_has_no_exam_management',IF(COUNT(*)=0,'PASS','FAIL'),COUNT(*) FROM role_permissions rp JOIN roles r ON r.role_id=rp.role_id JOIN permissions p ON p.permission_id=rp.permission_id WHERE r.role_code='board_member' AND p.permission_code IN ('exams.manage','grades.manage');
INSERT INTO p01_verification SELECT 'legacy_units_reconciled',IF(COUNT(*)=0,'PASS','FAIL'),COUNT(*) FROM organizational_units WHERE unit_code IN ('VP_ADMIN','REG_OFFICE','EXAM_OFFICE') AND is_active=1;
