-- P0-1 VERIFY. Every category and OVERALL must be PASS; detail reports must be empty.
DROP TEMPORARY TABLE IF EXISTS p01_expected_units;
CREATE TEMPORARY TABLE p01_expected_units(unit_code VARCHAR(50) PRIMARY KEY,unit_name VARCHAR(200),type_code VARCHAR(50),parent_code VARCHAR(50) NULL);
DROP TEMPORARY TABLE IF EXISTS p01_expected_permissions;
CREATE TEMPORARY TABLE p01_expected_permissions(role_code VARCHAR(80),permission_code VARCHAR(120),PRIMARY KEY(role_code,permission_code));
DROP TEMPORARY TABLE IF EXISTS p01_verification;
CREATE TEMPORARY TABLE p01_verification(category VARCHAR(100) PRIMARY KEY,status VARCHAR(4),failures INT);
SELECT category,status,failures FROM p01_verification ORDER BY category;
SELECT e.unit_code,e.unit_name expected_name,e.type_code expected_type,e.parent_code expected_parent,u.unit_name actual_name,t.type_code actual_type,p.unit_code actual_parent,u.is_active,'OFFICIAL_CHART_MISMATCH' finding FROM p01_expected_units e LEFT JOIN organizational_units u ON u.unit_code=e.unit_code LEFT JOIN organizational_unit_types t ON t.unit_type_id=u.unit_type_id LEFT JOIN organizational_units p ON p.organizational_unit_id=u.parent_unit_id WHERE u.organizational_unit_id IS NULL OR NOT(u.unit_name<=>e.unit_name AND t.type_code<=>e.type_code AND p.unit_code<=>e.parent_code AND u.is_active=1);
SELECT 'OVERALL' category,IF(COUNT(*)=0,'PASS','FAIL') status,COUNT(*) failed_categories FROM p01_verification WHERE status='FAIL';
